/**
 * Count occurrences of a substring in a string
 */
static int count_substring(const char* str, const char* substr) {
    if (!str || !substr) return 0;
    
    int count = 0;
    const char* tmp = str;
    
    while ((tmp = strstr(tmp, substr)) != NULL) {
        count++;
        tmp += strlen(substr);
    }
    
    return count;
}

/**
 * Simple JSON parser to count widgets
 * This is a lightweight parser that doesn't need a full JSON library
 */
static void count_widgets_in_json(const char* json, 
                                 uint16_t* buttons, uint16_t* labels, 
                                 uint16_t* sliders, uint16_t* views,
                                 uint16_t* text_inputs, uint16_t* text_editors,
                                 uint16_t* total_children) {
    
    if (!json) return;
    
    // Count widget types by looking for "type": "widget_type" patterns
    *buttons = count_substring(json, "\"type\": \"button\"");
    *labels = count_substring(json, "\"type\": \"label\"");
    *sliders = count_substring(json, "\"type\": \"slider\"");
    *views = count_substring(json, "\"type\": \"view\"");
    *text_inputs = count_substring(json, "\"type\": \"text_input\"");
    *text_editors = count_substring(json, "\"type\": \"text_editor\"");
    
    // Count children by looking for "children": [ patterns
    *total_children = count_substring(json, "\"children\": [");
    
    // Also count items in children arrays (approximate)
    // Each "children" array item is a widget
    int open_brackets = 0;
    int in_children = 0;
    int child_count = 0;
    
    for (int i = 0; json[i]; i++) {
        if (strncmp(&json[i], "\"children\": [", 14) == 0) {
            in_children = 1;
            open_brackets = 1;
            i += 13;
            continue;
        }
        
        if (in_children) {
            if (json[i] == '[') open_brackets++;
            if (json[i] == ']') {
                open_brackets--;
                if (open_brackets == 0) {
                    in_children = 0;
                }
            }
            if (json[i] == '{') {
                child_count++;
            }
        }
    }
    
    // Add children to views (each view with children needs extra memory)
    if (child_count > *total_children) {
        *total_children = child_count;
    }
}

/**
 * Calculate memory for children arrays
 */
static uint32_t calculate_children_memory(uint16_t total_children) {
    // Each child pointer is 2 bytes (ESP8266 is 32-bit, pointers are 4 bytes)
    // But we're using uint8_t for children_count, so max 255 children per widget
    // For simplicity, assume each widget with children has 4 children on average
    // and each needs 4 pointers
    
    if (total_children == 0) return 0;
    
    // Approximate: 4 pointers per children array * 4 bytes each
    // This is a rough estimate; actual depends on widget structure
    return total_children * MEMORY_PER_CHILD_POINTER * 4;
}

/**
 * Calculate total memory required for widgets
 */
static uint32_t calculate_widget_memory(uint16_t buttons, uint16_t labels, 
                                       uint16_t sliders, uint16_t views,
                                       uint16_t text_inputs, uint16_t text_editors,
                                       uint16_t total_children) {
    
    uint32_t total = 0;
    
    // Add memory for each widget type
    total += buttons * MEMORY_WIDGET_BUTTON_SIZE;
    total += labels * MEMORY_WIDGET_LABEL_SIZE;
    total += sliders * MEMORY_WIDGET_SLIDER_SIZE;
    total += views * MEMORY_WIDGET_VIEW_SIZE;
    total += text_inputs * MEMORY_WIDGET_TEXT_INPUT_SIZE;
    total += text_editors * MEMORY_WIDGET_TEXT_EDITOR_SIZE;
    
    // Add memory for children pointers
    total += calculate_children_memory(total_children);
    
    // Add overhead for text buffers in labels, buttons, etc.
    // Each label/button with text needs buffer space
    uint16_t text_widgets = labels + buttons + text_inputs + text_editors;
    total += text_widgets * 64;  // Average text buffer size
    
    return total;
}

/**
 * Check if pool has capacity for widgets
 */
static bool check_pool_capacity(uint16_t buttons, uint16_t labels, 
                               uint16_t sliders, uint16_t views,
                               uint16_t text_inputs, uint16_t text_editors) {
    
    // Check each pool
    if (buttons > AVAILABLE_BUTTONS) return false;
    if (labels > AVAILABLE_LABELS) return false;
    if (sliders > AVAILABLE_SLIDERS) return false;
    if (views > AVAILABLE_VIEWS) return false;
    
    // For text inputs and editors, we use generic widget pool
    uint16_t generic_widgets = text_inputs + text_editors;
    if (generic_widgets > AVAILABLE_WIDGETS) return false;
    
    return true;
}

